  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Ecosystems, Food Webs and Energy Flow$j$, $j${"readings": [{"title": "Psalm 104 (King James Version)", "url": "/portal/bible/Psalms/104"}], "body": "Ecology is the study of how living things interact with each other and with their environment. Psalm 104:27 says, These wait all upon thee; that thou mayest give them their meat in due season.\n\nLevels of organization: organism, population (one species in an area), community (all the populations), ecosystem (the community plus the nonliving environment), biome (a large region with a similar climate) and biosphere (all of life on earth).\n\nBiotic factors are living parts (plants, animals, bacteria). Abiotic factors are nonliving parts (sunlight, water, temperature, soil, wind). A habitat is where an organism lives. A niche is its role: what it eats, where and when it lives, and how it affects others.\n\nRoles in an ecosystem:\nProducers make food (plants, algae).\nPrimary consumers eat producers (herbivores). Secondary consumers eat herbivores. Tertiary consumers eat other carnivores. Omnivores eat both.\nDecomposers (bacteria, fungi) break down dead matter and return nutrients to the soil.\n\nA food chain shows one path of energy: grass, grasshopper, frog, snake, hawk. A food web shows many connected food chains.\n\nEnergy flow: Energy enters ecosystems from the sun and moves through trophic levels. Only about 10 percent of energy passes to the next level; the rest is used for life processes or lost as heat. That is why there are fewer top predators than plants, and why an energy pyramid is wide at the bottom. If a producer has 10,000 units of energy, the primary consumer gets about 1,000, the secondary about 100 and the tertiary about 10.\n\nSymbiosis: Mutualism helps both (bees and flowers). Commensalism helps one and does not affect the other (a bird nesting in a tree). Parasitism helps one and harms the other (a tick on a dog). Other interactions: predation and competition.\n\nYour task: (1) Build a food chain with four organisms and label the trophic levels. (2) If the producers have 20,000 units of energy, how many reach the secondary consumers? (3) Give an example of mutualism and explain who benefits.\n\nFlorida standards: SC.912.L.17.9.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.17.9", "script": "Welcome to Unit 6. This is Dr. Jenkins. Listen, Psalm one hundred four and twenty seven says, These wait all upon thee; that thou mayest give them their meat in due season. Today we study how God has set up the household of life, which is ecology.\n\nEcology is the study of how living things interact with each other and with their environment. The levels of organization are organism, population, community, ecosystem, biome and biosphere. Biotic factors are living parts, like plants, animals and bacteria. Abiotic factors are nonliving parts, like sunlight, water, temperature, soil and wind. A habitat is where an organism lives. A niche is its role, what it eats, where and when it lives and how it affects others.\n\nNow watch this. Producers make food, like plants and algae. Primary consumers eat producers. Secondary consumers eat herbivores. Tertiary consumers eat other carnivores. Omnivores eat both. And decomposers, bacteria and fungi, break down dead matter and return nutrients to the soil. A food chain shows one path of energy, like grass, grasshopper, frog, snake, hawk. A food web shows many connected chains.\n\nLook at the energy flow. Energy enters from the sun and moves through the trophic levels. Only about ten percent passes to the next level. The rest is used for life processes or lost as heat. That is why there are fewer top predators than plants. If the producers have ten thousand units of energy, the primary consumer gets about one thousand, the secondary about one hundred, and the tertiary about ten.\n\nFinally, symbiosis. Mutualism helps both, like bees and flowers. Commensalism helps one and does not affect the other, like a bird nesting in a tree. Parasitism helps one and harms the other, like a tick on a dog. Then there are predation and competition.\n\nYour task today. Build a four organism food chain and label the levels. Find how much energy of twenty thousand units reaches the secondary consumers. And give an example of mutualism. Take the four question check when you finish.\n\nHe gives food in due season to all. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Ecosystems, Food Webs and Energy Flow$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Cycles of Matter: Water, Carbon and Nitrogen$j$, $j${"readings": [{"title": "Ecclesiastes 1 (King James Version)", "url": "/portal/bible/Ecclesiastes/1"}], "body": "Energy flows in one direction through an ecosystem, but matter is recycled. Atoms of carbon, nitrogen and water are used again and again. Ecclesiastes 1:7 says, All the rivers run into the sea; yet the sea is not full; unto the place from whence the rivers come, thither they return again.\n\nThe water cycle: Evaporation (water becomes vapor from oceans and lakes), transpiration (plants release water vapor), condensation (vapor forms clouds), precipitation (rain, snow), runoff and infiltration (water flows over land or soaks into groundwater). The sun powers the cycle.\n\nThe carbon cycle: Carbon is the backbone of all biomolecules.\nPhotosynthesis takes carbon dioxide out of the air and puts carbon into sugars.\nCellular respiration, decomposition and burning return carbon dioxide to the air.\nConsumers get carbon by eating producers.\nFossil fuels (coal, oil, gas) are carbon stored from ancient organisms. Burning them adds carbon dioxide to the air faster than it is removed.\nThe ocean also absorbs carbon dioxide.\n\nThe nitrogen cycle: Nitrogen is needed for proteins and DNA. The air is about 78 percent nitrogen gas, but most organisms cannot use it.\nNitrogen fixation: certain bacteria (some live in the roots of legumes like beans) change nitrogen gas into ammonia.\nNitrification: other bacteria change ammonia into nitrates, which plants can absorb.\nAssimilation: plants build nitrates into proteins, and animals eat the plants.\nDecomposers return nitrogen as ammonia.\nDenitrification: some bacteria return nitrogen gas to the air.\nFarmers use fertilizer and rotate crops with legumes to put nitrogen back in the soil. Excess fertilizer can run into water and cause algae blooms (eutrophication) that use up the oxygen.\n\nYour task: (1) Trace one carbon atom from the air through a plant, a rabbit and a fox and back to the air. (2) Explain why bacteria are important to the nitrogen cycle. (3) Tell how burning fossil fuels affects the carbon cycle.\n\nFlorida standards: SC.912.L.17.9.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.17.9", "script": "Welcome back. Dr. Jenkins here. Listen, Ecclesiastes one and seven says, All the rivers run into the sea; yet the sea is not full; unto the place from whence the rivers come, thither they return again. Energy flows one way through an ecosystem, but matter is recycled, again and again.\n\nStart with the water cycle. Evaporation turns water into vapor from oceans and lakes. Transpiration is when plants release water vapor. Condensation forms clouds. Precipitation brings rain and snow. Runoff and infiltration move water over land or into groundwater. The sun powers the whole cycle.\n\nNow watch this. The carbon cycle. Carbon is the backbone of all biomolecules. Photosynthesis takes carbon dioxide out of the air and puts the carbon into sugars. Consumers get carbon by eating producers. Cellular respiration, decomposition and burning return carbon dioxide to the air. Fossil fuels, coal, oil and gas, are carbon stored from ancient organisms, and burning them adds carbon dioxide to the air faster than it is removed. The ocean also absorbs carbon dioxide.\n\nLook at the nitrogen cycle. Nitrogen is needed for proteins and DNA. The air is about seventy eight percent nitrogen gas, but most organisms cannot use it. In nitrogen fixation, certain bacteria, some living in the roots of beans and other legumes, change nitrogen gas into ammonia. In nitrification, other bacteria change ammonia into nitrates that plants can absorb. In assimilation, plants build nitrates into proteins, and animals eat the plants. Decomposers return nitrogen as ammonia. In denitrification, some bacteria return nitrogen gas to the air.\n\nFarmers add fertilizer and rotate crops with legumes to put nitrogen back in the soil. But too much fertilizer can wash into water and cause algae blooms, called eutrophication, that use up the oxygen.\n\nYour task today. Trace one carbon atom through a plant, a rabbit and a fox and back to the air. Explain why bacteria matter in the nitrogen cycle. And tell how burning fossil fuels affects the carbon cycle. Take the four question check when you finish.\n\nNothing in His design is wasted. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Cycles of Matter: Water, Carbon and Nitrogen$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Populations, Carrying Capacity and Biodiversity$j$, $j${"readings": [{"title": "Matthew 6 (King James Version)", "url": "/portal/bible/Matthew/6"}], "body": "A population changes over time as individuals are born, die, arrive and leave. Matthew 6:26 says, Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they?\n\nPopulation change equals births plus immigration minus deaths minus emigration. Population density is the number of individuals per unit of area.\n\nGrowth patterns:\nExponential growth: the population grows faster and faster when resources are unlimited, producing a J shaped curve.\nLogistic growth: growth slows and levels off at the carrying capacity (K), producing an S shaped curve. Carrying capacity is the largest population an environment can support.\n\nLimiting factors keep populations below unlimited growth.\nDensity dependent factors depend on how crowded the population is: competition, predation, disease, food supply.\nDensity independent factors affect a population no matter its size: hurricanes, fires, floods, freezes. Florida wildlife is affected by hurricanes and drought.\n\nPredator and prey numbers rise and fall in linked cycles.\n\nBiodiversity is the variety of life. It includes genetic diversity (variety within a species), species diversity (the number of kinds in an area) and ecosystem diversity. High biodiversity makes an ecosystem more stable and better able to recover from change. The Everglades, mangrove forests and coral reefs near Pompano Beach are rich in life. A keystone species has a large effect on its ecosystem; mangroves and sea otters are examples of species whose loss changes everything.\n\nInvasive species are nonnative species that spread and harm native species because they lack natural predators. In Florida, the Burmese python, lionfish and Brazilian pepper are problems.\n\nSuccession is the gradual change in a community. Primary succession begins on bare rock with no soil, such as new volcanic land, with pioneer species like lichens. Secondary succession follows a disturbance such as a fire or hurricane, where soil remains, and it is faster.\n\nYour task: (1) Find the population change if there are 40 births, 25 deaths, 10 immigrants and 5 emigrants. (2) Draw or describe the J and S curves and mark carrying capacity. (3) Explain why invasive species can harm Florida ecosystems.\n\nFlorida standards: SC.912.L.17.5.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.17.5", "script": "Welcome back. Dr. Jenkins here. Listen, Matthew six and twenty six says, Behold the fowls of the air: for they sow not, neither do they reap, nor gather into barns; yet your heavenly Father feedeth them. Are ye not much better than they? Today we study how populations grow and what keeps them in balance.\n\nPopulation change equals births plus immigration minus deaths minus emigration. Population density is the number of individuals per unit of area.\n\nNow watch this. With unlimited resources, a population shows exponential growth, a J shaped curve, growing faster and faster. In real life, growth slows and levels off at the carrying capacity, called K, and that gives an S shaped curve, which we call logistic growth. Carrying capacity is the largest population an environment can support.\n\nLimiting factors hold a population back. Density dependent factors depend on how crowded the population is, such as competition, predation, disease and food supply. Density independent factors affect a population no matter its size, such as hurricanes, fires, floods and freezes. In Florida, hurricanes and drought affect wildlife every year. Predator and prey numbers rise and fall in linked cycles.\n\nLook at biodiversity, the variety of life. It includes genetic diversity, species diversity and ecosystem diversity. High biodiversity makes an ecosystem more stable and better able to recover. The Everglades, mangrove forests and coral reefs near Pompano Beach are rich with life. A keystone species has a large effect on its ecosystem, and losing it changes everything.\n\nInvasive species are nonnative species that spread and harm native species because they have no natural predators. In Florida, the Burmese python, lionfish and Brazilian pepper are problems.\n\nSuccession is the gradual change in a community. Primary succession begins on bare rock with no soil, with pioneer species like lichens. Secondary succession follows a disturbance such as a fire or hurricane where soil remains, and it is faster.\n\nYour task today. Find the population change with forty births, twenty five deaths, ten immigrants and five emigrants. Describe the J and S curves. And explain why invasive species harm Florida ecosystems. Take the four question check when you finish.\n\nIf He feeds the birds, He will guide our stewardship. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Populations, Carrying Capacity and Biodiversity$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Human Impact, Health and Stewardship$j$, $j${"readings": [{"title": "Psalm 24 (King James Version)", "url": "/portal/bible/Psalms/24"}], "body": "God gave people the care of His creation. Psalm 24:1 says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein. Genesis 2:15 says, And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it. To dress and to keep is the idea of stewardship.\n\nHuman impacts on ecosystems:\nHabitat loss and fragmentation from building and farming.\nPollution of air, water and soil. Biomagnification is when a toxin such as mercury or DDT builds up in higher concentrations at each higher trophic level.\nOverharvesting and overfishing.\nInvasive species moved by people.\nClimate change: burning fossil fuels adds carbon dioxide, a greenhouse gas that traps heat. Scientists observe rising average temperatures and sea levels, which matter for coastal Florida. People weigh solutions in different ways.\nResource use: renewable resources (sunlight, wind, trees if replanted) and nonrenewable resources (coal, oil).\n\nStewardship and conservation: protect habitats and parks, reduce, reuse and recycle, use energy wisely, restore wetlands and reefs, control invasive species, and base decisions on evidence.\n\nHealth and the body's defenses: A healthy environment supports healthy people. Pathogens are disease causing organisms and viruses: bacteria, viruses, fungi and parasites. The body has defenses.\nNonspecific defenses: skin, mucus, stomach acid, inflammation, fever and white blood cells called phagocytes that engulf invaders.\nSpecific defenses (the immune system): White blood cells called lymphocytes. B cells make antibodies that mark a pathogen. T cells destroy infected cells or help coordinate the response. Memory cells remember a pathogen so the next infection is stopped faster.\nVaccines expose the body to a harmless form of a pathogen so it builds memory cells without getting the disease. Antibiotics kill bacteria but not viruses. HIV attacks helper T cells and weakens the immune system. Allergies are overreactions to harmless substances, and autoimmune diseases occur when the immune system attacks the body's own cells.\n\nHealthy habits: wash hands, sleep, eat well, keep up with vaccines, and stay active.\n\nYour task: (1) Explain biomagnification with an example. (2) Tell the difference between nonspecific and specific defenses. (3) Write three ways a student can practice stewardship.\n\nFlorida standards: SC.912.L.17.20, SC.912.L.14.52.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.L.17.20, SC.912.L.14.52", "script": "Welcome back. Dr. Jenkins here. Listen, Psalm twenty four and one says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein. And Genesis two and fifteen says, And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it. To dress and to keep is stewardship, and it is our calling.\n\nNow watch this. People affect ecosystems in many ways. Habitat loss and fragmentation from building and farming. Pollution of air, water and soil. Biomagnification, where a toxin like mercury or DDT builds up in higher concentrations at each higher trophic level. Overharvesting and overfishing. Invasive species moved by people. And climate change, since burning fossil fuels adds carbon dioxide, a greenhouse gas that traps heat. Scientists observe rising average temperatures and sea levels, which matter for coastal Florida, and people weigh the solutions in different ways. Resources are either renewable, like sunlight, wind and trees if replanted, or nonrenewable, like coal and oil.\n\nStewardship looks like this. Protect habitats and parks. Reduce, reuse and recycle. Use energy wisely. Restore wetlands and reefs. Control invasive species. And base decisions on evidence.\n\nNow health. A healthy environment supports healthy people. Pathogens are disease causing organisms and viruses, including bacteria, viruses, fungi and parasites. The body has nonspecific defenses first: skin, mucus, stomach acid, inflammation, fever, and white blood cells called phagocytes that engulf invaders. Then specific defenses, the immune system. Lymphocytes do the work. B cells make antibodies that mark a pathogen. T cells destroy infected cells or help coordinate the response. Memory cells remember a pathogen so the next infection is stopped faster.\n\nA vaccine exposes the body to a harmless form of a pathogen so it builds memory cells without getting the disease. Antibiotics kill bacteria but not viruses. HIV attacks helper T cells and weakens the immune system. Allergies are overreactions to harmless substances, and autoimmune diseases happen when the immune system attacks the body's own cells. Healthy habits help: wash your hands, sleep, eat well, keep up with vaccines and stay active.\n\nYour task today. Explain biomagnification with an example. Tell the difference between nonspecific and specific defenses. And write three ways a student can practice stewardship. Take the four question check when you finish.\n\nWe keep the garden and care for the body He gave us. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Human Impact, Health and Stewardship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Ecosystem Study and Stewardship Plan$j$, $j${"prompt": "Part 1: Food Web and Energy. Draw or describe a food web with at least eight organisms from a Florida ecosystem such as the Everglades, a mangrove forest or a coral reef. Label producers, consumers and decomposers. Pick one food chain from it and use the 10 percent rule to show the energy at each level starting with 50,000 units in the producers. Psalm 24:1 says, The earth is the LORD's, and the fulness thereof; the world, and they that dwell therein.\n\nPart 2: Cycles. Draw or describe the carbon cycle or the nitrogen cycle with at least six labeled steps and tell the role of the living things in it.\n\nPart 3: Population Study. A population of 200 rabbits has 60 births, 30 deaths, 12 immigrants and 8 emigrants in one year. Find the new population, then explain what could cause its growth to level off at the carrying capacity.\n\nPart 4: Health. Explain how the body defends itself against a virus and how a vaccine helps. Name one healthy habit that supports the immune system.\n\nPart 5: Stewardship Plan. Write a plan of at least 100 words for your school or church to care for creation. Include three specific actions, one way to measure results and one Bible verse. Genesis 2:15 says, And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it.", "rubric": "70 points. Food web and energy: 16 points. Cycles: 12 points. Population study: 12 points. Health: 12 points. Stewardship plan: 14 points. Clear work and complete sentences: 4 points. A score of 49 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Ecosystem Study and Stewardship Plan$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: Keeping the Garden$j$, $j${"prompt": "Write a post of at least 120 words that (1) explains in your own words why energy flows through an ecosystem while matter is recycled, (2) describes one human action that harms an ecosystem and one action that helps it, (3) tells how caring for creation and caring for our own bodies are both part of stewardship, and (4) connects your answer to Genesis 2:15, which says, And the LORD God took the man, and put him into the garden of Eden to dress it and to keep it. Then write a respectful reply of at least 40 words to another student, or answer this question: Why does a food web with many species tend to be more stable than one with few species? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: Keeping the Garden$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Ecosystems, Food Webs and Energy Flow$j$, $j${"questions": [{"q": "Organisms that make their own food in an ecosystem are:", "options": ["Decomposers", "Secondary consumers", "Parasites", "Producers"]}, {"q": "About what percent of energy passes from one trophic level to the next?", "options": ["10 percent", "100 percent", "90 percent", "50 percent"]}, {"q": "A relationship in which both organisms benefit is:", "options": ["Mutualism", "Predation", "Competition", "Parasitism"]}, {"q": "Fungi and bacteria that break down dead organisms are:", "options": ["Producers", "Decomposers", "Predators", "Primary consumers"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Ecosystems, Food Webs and Energy Flow$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,0,1}'::int[], array[$j$Producers capture energy by photosynthesis.$j$,$j$About 10 percent is passed on and the rest is used or lost as heat.$j$,$j$Mutualism helps both species.$j$,$j$Decomposers return nutrients to the ecosystem.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Ecosystems, Food Webs and Energy Flow$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Cycles of Matter: Water, Carbon and Nitrogen$j$, $j${"questions": [{"q": "Which process removes carbon dioxide from the air?", "options": ["Decomposition", "Photosynthesis", "Burning fuel", "Respiration"]}, {"q": "Bacteria that change nitrogen gas into ammonia carry out:", "options": ["Denitrification", "Transpiration", "Fermentation", "Nitrogen fixation"]}, {"q": "The release of water vapor from plant leaves is:", "options": ["Condensation", "Runoff", "Precipitation", "Transpiration"]}, {"q": "Excess fertilizer in a lake can cause:", "options": ["No change", "Less nitrogen everywhere", "An algae bloom that lowers the oxygen", "More oxygen at the bottom"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Cycles of Matter: Water, Carbon and Nitrogen$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,3,2}'::int[], array[$j$Producers use carbon dioxide to make sugars.$j$,$j$Nitrogen fixation makes nitrogen usable by plants.$j$,$j$Plants release water vapor through stomata.$j$,$j$Eutrophication happens when extra nutrients cause rapid algae growth.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Cycles of Matter: Water, Carbon and Nitrogen$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Populations, Carrying Capacity and Biodiversity$j$, $j${"questions": [{"q": "The largest population an environment can support is the:", "options": ["Biodiversity", "Carrying capacity", "Niche", "Succession"]}, {"q": "A hurricane limiting a population is an example of a:", "options": ["Density dependent factor", "Mutualism", "Density independent factor", "Producer"]}, {"q": "Population change with 40 births, 25 deaths, 10 immigrants and 5 emigrants is:", "options": ["Plus 30", "Plus 15", "Plus 20", "Minus 20"]}, {"q": "Which is an invasive species in Florida?", "options": ["Red mangrove", "Manatee", "Burmese python", "Sea oats"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Populations, Carrying Capacity and Biodiversity$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,2}'::int[], array[$j$Carrying capacity is limited by resources.$j$,$j$A hurricane affects a population regardless of its density.$j$,$j$40 minus 25 plus 10 minus 5 equals 20.$j$,$j$The Burmese python is a nonnative species that harms native wildlife.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Populations, Carrying Capacity and Biodiversity$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Human Impact, Health and Stewardship$j$, $j${"questions": [{"q": "The buildup of a toxin at higher trophic levels is called:", "options": ["Fermentation", "Succession", "Biomagnification", "Transpiration"]}, {"q": "Which is a nonrenewable resource?", "options": ["Wind", "Replanted trees", "Coal", "Sunlight"]}, {"q": "B cells help protect the body by making:", "options": ["Antibodies", "Enzymes for photosynthesis", "Antibiotics", "Chlorophyll"]}, {"q": "A vaccine works by helping the body to:", "options": ["Build memory cells without getting the disease", "Avoid all pathogens forever", "Kill all bacteria directly", "Make more DNA"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Human Impact, Health and Stewardship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,0,0}'::int[], array[$j$Toxins like mercury become more concentrated up the food chain.$j$,$j$Coal forms over millions of years and cannot be replaced quickly.$j$,$j$B cells produce antibodies that mark pathogens.$j$,$j$A vaccine prepares the immune system for a future exposure.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Human Impact, Health and Stewardship$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Ecology, Stewardship and Health$j$, $j${"questions": [{"q": "Which statement about energy and matter in an ecosystem is correct?", "options": ["Matter flows one way and energy is recycled", "Neither moves", "Energy flows one way and matter is recycled", "Both are recycled completely"]}, {"q": "In a food chain, a hawk that eats a snake that eats a frog that eats a grasshopper is a:", "options": ["Decomposer", "Producer", "Tertiary or higher consumer", "Primary consumer"]}, {"q": "If a primary consumer gets 5,000 units of energy, the secondary consumer gets about:", "options": ["500 units", "50 units", "5,000 units", "50,000 units"]}, {"q": "The part of the nitrogen cycle done by bacteria in legume roots is:", "options": ["Evaporation", "Photosynthesis", "Transpiration", "Nitrogen fixation"]}, {"q": "An S shaped growth curve that levels off shows:", "options": ["Succession", "Extinction", "Logistic growth at carrying capacity", "Exponential growth without limits"]}, {"q": "Biodiversity helps ecosystems because:", "options": ["More variety makes them less stable", "It reduces the number of species", "It stops all change", "More variety makes them more stable"]}, {"q": "Burning fossil fuels increases which gas in the air?", "options": ["Nitrogen gas only", "Argon", "Helium", "Carbon dioxide"]}, {"q": "Memory cells in the immune system:", "options": ["Carry oxygen", "Digest food", "Make chlorophyll", "Help the body respond faster to a pathogen it has seen before"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Ecology, Stewardship and Health$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,0,3,2,3,3,3}'::int[], array[$j$Energy is lost as heat while atoms are reused.$j$,$j$It is at the top of the chain as a high level consumer.$j$,$j$About 10 percent is passed on.$j$,$j$These bacteria change nitrogen gas into a usable form.$j$,$j$Growth slows as the population nears carrying capacity.$j$,$j$Many species give the ecosystem more ways to recover from change.$j$,$j$Combustion releases carbon from ancient organisms as carbon dioxide.$j$,$j$Memory cells remain after an infection or vaccination.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Ecology, Stewardship and Health$j$ on conflict (item_id) do nothing;
